# Find all components
def find_all_components(grid):
    h, w = len(grid), len(grid[0])
    visited = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r, c) not in visited:
                component = []
                queue = deque([(r, c)])
                while queue:
                    cr, cc = queue.popleft()
                    component.append((cr, cc))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 2 and (nr, nc) not in visited:
